int main() {
    int n, k;
    scanf("%d%d", &n, &k);
    c[0] = 1;
    for(int i=1; i<=n; i++) {
        f[i] = (qpow(k, i)-qpow(k-1, i)+mod)%mod;
        c[i] = c[i-1]*(n-i+1)%mod*qpow(i, mod-2)%mod;
    }
    long long ans = qpow(f[n], n)%mod;
    int flag = -1;
    for(int i=1; i<=n; i++) {
        long long tmp = c[i]*qpow(f[n-i], n)%mod*qpow(qpow(k-1, n)%mod, i)%mod;
