    vector<pair<int,double>>val(n+1);

    vector<bool>vis(n+1);



    function<void(int)>dfs = [&](int a) {

        for(auto [b,c]:adj[a]) {

            if(!vis[b]) {

                vis[b] = true;

                val[b].second = c-val[a].second;

                val[b].first = -val[a].first;

                dfs(b);

            }   

        }

    };



    for(int i=1;i<=n;i++) {

        if(vis[i]) continue;

        vis[i] = true;

        val[i] = {1,0};

        dfs(i);

    }



    for(auto [a,b,c]:edges) {

        int x = val[a].first+val[b].first;

        double y = val[a].second+val[b].second;



