            cout<<"NO\n";

            return;

        }



        if(x == 0) continue;



        y = (c-y)/x;

        val[a].second += val[a].first*y;

        val[a].first = 0; 

    }



    for(int i=1;i<=n;i++) vis[i] = false;



    function<void(int)>dfs1 = [&](int a) {

        for(auto [b,c]:adj[a]) {

            if(!vis[b]) {

                vis[b] = true;

                val[b] = {0,c-val[a].second};

                dfs1(b);

            }

        }

    };



    for(int i=1;i<=n;i++) {

        if(val[i].first == 0 and !vis[i]) {

            vis[i] = true;

            dfs1(i);

        }

    }



    for(auto [a,b,c]:edges) {

        int x = val[a].first+val[b].first;

        double y = val[a].second+val[b].second;



        if(x == 0 and !isEqual(c,y)) {

            cout<<"NO\n";

            return;

        }



        if(x == 0) continue;



        y = (c-y)/x;

        val[a].second += val[a].first*y;

        val[a].first = 0; 

    }



    for(int i=1;i<=n;i++) {

        vis[i] = false;

    }



    vector<int>nodes;

    function<void(int)>dfs2 = [&](int s) {

        if(vis[s]) return;

        vis[s] = true;

        nodes.push_back(s);

        for(auto [b,c]:adj[s]) {

            dfs2(b);

        }

    };



