int n, m, q;
char S[maxN * maxL];

struct Word
{
    char s[maxL];

    bool operator < (const Word &a) const
    {
        if (strcmp(s, a.s) <= 0)
            return 1;
        return 0;
    }
} word[maxN];

int bs(char *p)
{
    int i = 0, q = 1 << 16;
    while (q)
    {
        if (i + q <= n && (strcmp(p, word[i + q].s) >= 0))
            i += q;
        q >>= 1;
    }
    return i;
}

int f[2 * maxN];
int root(int x)
{
    if (!f[x] || f[x] == x)
        return x;
    return f[x] = root(f[x]);
}

void Union(int x, int y)
{
    int rx = root(x), ry = root(y);
    if (rx != ry)
        f[rx] = ry;
}

void read()
{
    scanf("%d %d %d\n", &n, &m, &q);
    gets(S);
    char *p = strtok(S, " ");
    int i = 0;
    while (p != NULL)
    {
        ++ i;
        strcpy(word[i].s, p);
        //word[i].idx = i;
        p = strtok(NULL, " ");
    }
}

void solve()
{
    sort(word + 1, word + n + 1); /// sort ---> but better trie
    while (m --)
    {
        int t;
        char *p;

        scanf("%d ", &t);
        gets(S + 1);
        p = strtok(S + 1, " ");
        int x = bs(p);
        p = strtok(NULL, " ");
        int y = bs(p);

        if (t == 1)
        {
            if (root(x + n) == root(y))
                printf("NO\n");
            else
            {
                printf("YES\n");
                Union(x, y);
                Union(x + n, y + n);
            }

        }
        else
        {
            if (root(x) == root(y))
                printf("NO\n");
            else
            {
                printf("YES\n");
                Union(x + n, y);
                Union(x, y + n);
            }
        }
    }
}

void write()
{
    while (q --)
    {
        gets(S + 1);
        char *p;

        p = strtok(S + 1, " ");
        int x = bs(p);
        p = strtok(NULL, " ");
        int y = bs(p);
        int rx = root(x), ry = root(y),
            rX = root(x + n);
        if (rx == ry)
            printf("1\n");
        else if (rX == ry)
            printf("2\n");
        else
            printf("3\n");
    }
}

int main()
{
    read();
    solve();
    write();

    return 0;
}

