int root(int v) {

	return par[v] < 0 ? v : par[v] = root(par[v]);

}



int add(int v) {

	present[v] = true;

	for (int i = 0; i < g[v].size(); i++)

		if (present[g[v][i].first]) {

			par[v] += par[g[v][i].first];

			par[g[v][i].first] = v;

		}

	return -par[v];

}



void erase(int v) {

	present[v] = false;

	par[root(v)]++;

}



