inline void prep(void){
	for(int i = 0; i < n; i++){
		for(int j = 0; j < 3; qqq[j++][i].pos = i);
		for(int j = 0; j < m; j++){
			int p = 0;
			switch(mmp[i][j]){
				case '*':
				case '&':
				case '#': p = 0; break;
				case '0' ... '9': p = 1; break;
				case 'a' ... 'z': p = 2; break;
			}
			int d = std::min(j, m - j);
			qqq[p][i].dis = std::min(qqq[p][i].dis, d);
		}
	}

}

inline bool check(int p1, int d1, int p2, int d2){
	bool flags[3] = {false, false, false};
	for(int i = 0; i < n; i++){
		if(i == p1) flags[d1] = true;
		else if(i == p2) flags[d2] = true;
		else{
			if(mmp[i][0] >= 'a' && mmp[i][0] <= 'z') flags[2] = true;
			else if(mmp[i][0] >= '0' && mmp[i][0] <= '9') flags[1] = true;
			else flags[0] = true;
		}
	}
	return flags[0] && flags[1] && flags[2];
}





