int n, m, d, cnt, tot, ans, Dfn[N], Low[N], Stack[N], Num[N], Dp[N][K], Head[N], Gcd[N], V[N][K], Del[N], Deg[N], Q[N];
bool Flag[N], Vis[N][K];
char str[N][K];
vector <int> Vec[N], Scc[N];
set <int> Set[N];
Pii q[(N) * (K)];

struct Edge
{
	int next, node, pre, nxt;
