  for (int i = 0; i < n; ++i) {
    deg[x[i]] += 1;
  }
  vector<bool> z(n, false);
  queue<int> Q;
  for (int i = 0; i < n; ++i) {
    if (deg[i] == 0) {
      Q.push(i);
      z[i] = true;
    }
  }
  while (!Q.empty()) {
    int to = x[Q.front()];
    Q.pop();
    if (--deg[to] == 0) {
      Q.push(to);
      z[to] = true;
    }
  }
  fill(deg.begin(), deg.end(), 0);
  for (int i = 0; i < n; i++) {
    deg[x[i]] += 1;
  }
  const auto backup = z;
  Mint ans = 1;
  for (int i = 0; i < n; i++) {
    if (z[i]) continue;
    vector<int> seq;
    int p = i;
    while (!z[p]) {
      seq.push_back(p);
      z[p] = true;
      p = x[p];
    }
    int sz = seq.size();
    int sum = 0;
    for (int j : seq) sum += deg[j];
    for (int b = 0; b < seq.size(); ++b) {
      for (int j : g[seq[b]]) {
        if (backup[j]) seq.push_back(j);
      }
    }
    Mint cur = 1;
    for (int j = 0; j < sz; ++j) {
      cur *= deg[seq[j]] + 1;
    }
    cur -= sum;
    for (int j = sz; j < seq.size(); ++j) {
      cur *= deg[seq[j]] + 1;
    }
    ans *= cur;
  }
  cout << ans << '\n';
  return 0;
}

