struct node {
	node *l, *r;
	ll sum;
	ll x;
	node() {
		l = r = 0;
		sum = x = 0;
	}
};

void upd(node *g, int v, int h, int d) {
	g->sum += d;
	if (h == 0) {
		g->x += d;
		return;
	}
	if (v & 1) {
		if (!g->r)
			g->r = new node();
		upd(g->r, v >> 1, h - 1, d);
	}
	else {
		if (!g->l)
			g->l = new node();
		upd(g->l, v >> 1, h - 1, d);
	}
}

double run(node *g, ll mx) {
	if (g->l) {
		if (g->r) {
			if (g->l->sum >= g->r->sum) {
				double ans = max(mx, g->l->sum + g->x) / 2.0;
				ans += run(g->l, max(mx, g->x + g->r->sum)) / 2.0;
				return ans;
			}
			else {
				double ans = max(mx, g->r->sum + g->x) / 2.0;
				ans += run(g->r, max(mx, g->x + g->l->sum)) / 2.0;
				return ans;
			}
		}
		else {
			double ans = max(mx, g->l->sum + g->x) / 2.0;
			ans += run(g->l, max(mx, g->x)) / 2.0;
			return ans;
		}
	}
	else {
		if (g->r) {
			double ans = max(mx, g->r->sum + g->x) / 2.0;
			ans += run(g->r, max(mx, g->x)) / 2.0;
			return ans;
		}
		else {
			return max(mx, g->sum);
		}
	}
}


