void scc( int u ){
	low[u] = num[u] = ++idx;
	instk[u] = 1;
	stk.push_back(u);

	for ( int i = 0; i < f[u].size(); i++ ){
		edge e = f[u][i];
		if ( num[e.v] == 0 ){
			scc(e.v);
			low[u] = min( low[u] , low[e.v]);
		}

		if ( instk[e.v] ){
			low[u] = min( low[u], num[e.v]);
		}
	}

	if ( low[u] == num[u] ){
		gidx++;
		while (1 ){
			int x = stk.back();
			con[x] = gidx;
			instk[x] = 0;
			stk.pop_back();

			if ( x == u ) break;
		}
	}
}

LL solve( LL n , LL init ){
	LL u0 = -1;
	LL u1 = -1;
	LL u2 = init;
	LL res = (n) * u2 ;
	res += (n) * (n-1) / 2 * -1;
	res += (n) * (n-1) * (n-2) / 6 * -1;

	return res;
}

LL un( LL n ,LL init){
	LL u0 = -1;
	LL u1 = -1;
	LL u2 = init;
	LL res = u2;
	res += (n-1)*u1;
	res += (n-1)*(n-2)/2*u0;
	return res;
}

LL bs( LL lo, LL hi , LL init){

	while (1 ){

		if ( hi - lo <= 1 ){
			if ( un(hi,init) >= 0 ) return hi;
			return lo;
		}
		LL mid = ( lo + hi ) / 2;

		if ( un(mid,init) >= 0 ) lo = mid;
		else hi = mid; 
	}
}

LL calc( LL z ){

	LL lim = bs(0,1e6,z);
	//cout << lim << endl;
	return solve(lim,z);
}

LL rek(int u ){
	if ( dp[u] != -1 ) return dp[u];
	dp[u] = point[u];

	for ( int i = 0; i < ch[u].size(); i++ ){
		edge e = ch[u][i];
		dp[u] = max( dp[u], point[u] + rek(e.v) + e.z );
	}

	return dp[u];
}

