const int N = 101;
const int MOD = (int)1e9 + 7;

using Poly = std::vector<int>;

int n, binom[N][N], pow[N], res[N];
std::vector<int> graph[N];
Poly dp[N][N];

void update(int&x, int a)
{
    x += a;
    if (x >= MOD) {
        x -= MOD;
    }
}

void ensure(Poly& p, int sz)
{
    if ((int)p.size() < sz) {
        p.resize(sz);
    }
}

int dfs(int p, int u)
{
    int sz = 1;
    dp[u][1] = { 1 };
    for (auto v : graph[u]) {
        if (v == p) {
            continue;
        }
        int sub_sz = dfs(u, v);
        for (int i = sz; i >= 0; -- i) {
            Poly tmp;
            dp[u][i].swap(tmp);
            for (int j = 0; j <= sub_sz; ++ j) {
                ensure(dp[u][i + j], (int)tmp.size() + dp[v][j].size() - 1);
                for (int x = 0; x < tmp.size(); ++ x) {
                    for (int y = 0; y < dp[v][j].size(); ++ y) {
                        update(dp[u][i + j][x + y], 1LL * tmp[x] * dp[v][j][y] % MOD);
                    }
                }
            }
        }
        sz += sub_sz;
    }
    for (int i = 1; i <= sz; ++ i) {
        ensure(dp[u][0], (int)dp[u][i].size() + 1);
        for (int x = 0; x < (int)dp[u][i].size(); ++ x) {
            update(dp[u][0][x + 1], 1LL * dp[u][i][x] * i % MOD);
        }
    }
    return sz;
}

