#define N	200000
#define N_	(1 << 18)	/* N_ = pow2(ceil(log2(N + 1))) */

int *el[N], elo[N], *er[N], ero[N];

void append(int **ej, int *eo, int i, int j) {
	int o = eo[i]++;

	if (o >= 2 && (o & o - 1) == 0)
		ej[i] = (int *) realloc(ej[i], o * 2 * sizeof *ej[i]);
	ej[i][o] = j;
}

char cc[N + 1]; int ll[N], rr[N], mode;

int max_(int i, int j) {
	if (i == -1)
		return j;
	if (j == -1)
		return i;
	return (mode == -1 ? (ll[i] < ll[j] || ll[i] == ll[j] && rr[i] > rr[j]) : (rr[i] > rr[j] || rr[i] == rr[j] && ll[i] < ll[j])) ? i : j;
}

int st[N_ * 2], n_;

void build(int n) {
	int i;

	n_ = 1;
	while (n_ <= n)
		n_ <<= 1;
	for (i = 0; i < n_; i++)
		st[n_ + i] = i < n && cc[i] == '1' ? i : -1;
	for (i = n_ - 1; i > 0; i--)
		st[i] = max_(st[i << 1 | 0], st[i << 1 | 1]);
}

int query(int i, int x) {
	int l, r;

	if (mode == -1) {
		for (l = i + n_, r = n_ - 1 + n_; l <= r; l >>= 1, r >>= 1)
			if ((l & 1) == 1) {
				if ((i = st[l]) != -1 && ll[i] * 2 - rr[i] - 1 <= x) {
					while (l < n_)
						if ((i = st[l << 1 | 0]) != -1 && ll[i] * 2 - rr[i] - 1 <= x)
							l = l << 1 | 0;
						else
							l = l << 1 | 1;
					return l - n_;
				}
				l++;
			}
	} else {
		for (l = 0 + n_, r = i + n_; l <= r; l >>= 1, r >>= 1)
			if ((r & 1) == 0) {
				if ((i = st[r]) != -1 && rr[i] * 2 - ll[i] + 1 >= x) {
					while (r < n_)
						if ((i = st[r << 1 | 1]) != -1 && rr[i] * 2 - ll[i] + 1 >= x)
							r = r << 1 | 1;
						else
							r = r << 1 | 0;
					return r - n_;
				}
				r--;
			}
	}
	return -1;
}

int main() {
	int t;

	scanf("%d", &t);
	while (t--) {
		static int xxl[N], xxr[N], yyl[N], yyr[N], kkl[N], kkr[N], qu[N], dd[N];
		int n, h, hl, hr, i, j, l, l_, l1, r, r_, k, r1, lo, ro, cnt, lower, upper;
		long long ans;

		scanf("%d%s", &n, cc);
		for (i = 0; i < n; i++) {
			el[i] = (int *) malloc(2 * sizeof *el[i]), elo[i] = 0;
			er[i] = (int *) malloc(2 * sizeof *er[i]), ero[i] = 0;
		}
		for (i = 0, k = 0; i < n; i++) {
			kkl[i] = k = cc[i] == '0' ? k + 1 : 0;
			if (k > 1 && i >= (k - 1) * 2)
				append(er, ero, i - (k - 1) * 2, i);
		}
		for (i = n - 1, k = 0; i >= 0; i--) {
			kkr[i] = k = cc[i] == '0' ? k + 1 : 0;
			if (k > 1 && i + (k - 1) * 2 < n)
				append(el, elo, i + (k - 1) * 2, i);
		}
		for (i = 0; i < n; i++)
			if (cc[i] == '1') {
				lo = 0, ro = 0;
				while (1) {
					if (lo < elo[i])
						l_ = el[i][lo], l1 = l_ - kkl[l_] + 1, l = (l_ + i) / 2 + 1;
					else
						l_ = -1, l1 = -1, l = 0;
					if (ro < ero[i])
						r_ = er[i][ro], r1 = r_ + kkr[r_] - 1, r = (i + r_) / 2 - 1;
					else
						r_ = n, r1 = n, r = n - 1;
					if (lo < elo[i] && l * 2 - r - 1 <= l1)
						lo++;
					else if (ro < ero[i] && r * 2 - l + 1 >= r1)
						ro++;
					else {
						ll[i] = l, rr[i] = r;
						break;
					}
				}
			} else
				ll[i] = -1, rr[i] = -1;
		mode = -1, build(n);
		cnt = 0;
		for (i = n - 1; i >= 0; i--) {
			if (cc[i] == '0')
				while (cnt && kkl[j = qu[cnt - 1]] <= kkr[i]) {
					xxl[j] = j - i, yyl[j] = dd[cnt - 1];
					if (cnt >= 2)
						dd[cnt - 2] += dd[cnt - 1];
					cnt--;
				}
			for (ro = -1; ro < ero[i]; ro++) {
				if (ro == -1)
					r = i - 1, r_ = i - 1;
				else
					r = er[i][ro], r_ = r + kkr[r] - 1;
				l1 = query(r_ + 1, i), r1 = ro + 1 < ero[i] ? er[i][ro + 1] : n;
				if (l1 == -1)
					continue;
				lower = -1, upper = cnt;
				while (upper - lower > 1) {
					h = (lower + upper) / 2;
					if (qu[h] >= r1)
						lower = h;
					else
						upper = h;
				}
				hl = upper;
				lower = -1, upper = cnt;
				while (upper - lower > 1) {
					h = (lower + upper) / 2;
					if (qu[h] >= l1)
						lower = h;
					else
						upper = h;
				}
				hr = lower;
				if (hl <= hr) {
					dd[hr]++;
					if (hl > 0)
						dd[hl - 1]--;
				}
			}
			if (i == 0 || cc[i - 1] == '1')
				for (k = kkr[i] - 1; k >= 0; k--)
					qu[cnt] = i + k, dd[cnt] = 0, cnt++;
		}
		while (cnt) {
			j = qu[cnt - 1];
			xxl[j] = j - i, yyl[j] = dd[cnt - 1];
			if (cnt >= 2)
				dd[cnt - 2] += dd[cnt - 1];
			cnt--;
		}
		mode = 1, build(n);
		cnt = 0;
		for (j = 0; j < n; j++) {
			if (cc[j] == '0')
				while (cnt && kkr[i = qu[cnt - 1]] < kkl[j]) {
					xxr[i] = j - i, yyr[i] = dd[cnt - 1];
					if (cnt >= 2)
						dd[cnt - 2] += dd[cnt - 1];
					cnt--;
				}
			for (lo = -1; lo < elo[j]; lo++) {
				if (lo == -1)
					l = j + 1, l_ = j + 1;
				else
					l = el[j][lo], l_ = l - kkl[l] + 1;
				r1 = query(l_ - 1, j), l1 = lo + 1 < elo[j] ? el[j][lo + 1] : -1;
				if (r1 == -1)
					continue;
				lower = -1, upper = cnt;
				while (upper - lower > 1) {
					h = (lower + upper) / 2;
					if (qu[h] <= l1)
						lower = h;
					else
						upper = h;
				}
				hl = upper;
				lower = -1, upper = cnt;
				while (upper - lower > 1) {
					h = (lower + upper) / 2;
					if (qu[h] <= r1)
						lower = h;
					else
						upper = h;
				}
				hr = lower;
				if (hl <= hr) {
					dd[hr]++;
					if (hl > 0)
						dd[hl - 1]--;
				}
			}
			if (j + 1 == n || cc[j + 1] == '1')
				for (k = kkl[j] - 1; k >= 0; k--)
					qu[cnt] = j - k, dd[cnt] = 0, cnt++;
		}
		while (cnt) {
			i = qu[cnt - 1];
			xxr[i] = j - i, yyr[i] = dd[cnt - 1];
			if (cnt >= 2)
				dd[cnt - 2] += dd[cnt - 1];
			cnt--;
		}
		ans = 0;
		for (i = 0, k = 0; i < n; i++)
			ans += k = cc[i] == '0' ? 0 : k + 1;
		for (j = 0; j < n; j++)
			if (j + 1 < n && cc[j] == '0' && cc[j + 1] == '0')
				ans += yyl[j];
		for (i = n - 1; i >= 0; i--)
			if (i > 0 && cc[i] == '0' && cc[i - 1] == '0')
				ans += yyr[i];
		for (j = 0; j < n; j++)
			if (cc[j] == '0' && (j + 1 == n || cc[j + 1] == '1')) {
				i = j - kkl[j] + 1;
				ans += (long long) (xxl[j] - (j - i)) * yyr[i] + (long long) yyl[j] * (xxr[i] - (j - i)) - (long long) yyl[j] * yyr[i];
			}
		printf("%lld\n", ans);
		for (i = 0; i < n; i++)
			free(el[i]), free(er[i]);
	}
	return 0;
}

