using namespace std;

const int MAXN = 100005;

struct Edge
{
	int to;
	int nxt;
}edge[MAXN << 1];

int n,id,ans;
int first[MAXN];
int f[MAXN][2][2];

void addE(int u,int v)
{
	edge[++id] = (Edge){v,first[u]};
	first[u] = id;
}

void dfs(int u,int fa)
{
	int deg = 0;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			deg++;
			dfs(edge[i].to,u);
		}
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
			f[u][1][0] = max(f[u][1][0],max(f[edge[i].to][1][0],f[edge[i].to][1][1]) + deg - 1);
	f[u][0][0] = f[u][1][0];
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
			f[u][0][0] = max(f[u][0][0],max(f[edge[i].to][0][0],f[edge[i].to][0][1]));
	int MX = 0,MX2 = 0;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			int v = max(f[edge[i].to][1][0],f[edge[i].to][1][1]);
			if (v >= MX)
			{
				MX2 = MX;
				MX = v;
			}
			else if (v > MX2)
				MX2 = v;
		}
	f[u][0][0] = max(f[u][0][0],MX + MX2 + max(0,deg - 2));
	ans = max(ans,MX + MX2 + deg - (bool)MX - (bool)MX2 + (bool)fa);
	MX = 0,MX2 = 0;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			int v = f[edge[i].to][1][0];
			if (v >= MX)
			{
				MX2 = MX;
				MX = v;
			}
			else if (v > MX2)
				MX2 = v;
		}
	f[u][0][1] = MX + MX2 + 1;
	f[u][1][1] = 1;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
			f[u][1][1] = max(f[u][1][1],f[edge[i].to][1][0] + 1);
//	for (int a = 0;a <= 1;a++)
//		for (int b = 0;b <= 1;b++)
//			cerr << "f[" << u << "][" << a << "][" << b << "]=" << f[u][a][b] << endl;
}

int main()
{
//	freopen("input.txt","r",stdin);
//	freopen("output1.txt","w",stdout);
	scanf("%d",&n);
	for (int u,v,i = 1;i < n;i++)
	{
		scanf("%d%d",&u,&v);
		addE(u,v);
		addE(v,u);
	}
	int rt = 1;
	dfs(rt,0);
	ans = max(ans,f[rt][0][0]);
	ans = max(ans,f[rt][0][1]);
	printf("%d\n",ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e6 + 5;
typedef long long ll;
const int mod = 1e9 + 7;
int add(int a, int b)
{
	a += b;
	return a >= mod ? a - mod : a;
}
int sub(int a, int b)
{
	a -= b;
	return a < 0 ? a + mod : a;
}
int mul(int a, int b) { return (ll)a * b % mod; }
int qpow(int a, int b)
{
	int ret = 1;
	for (; b; b >>= 1, a = mul(a, a))
		if (b & 1)
			ret = mul(ret, a);
	return ret;
}
/* math */
int fac[N], ifac[N];
inline void init(int n)
{
	ifac[0] = fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = mul(fac[i - 1], i);
	ifac[n] = qpow(fac[n], mod - 2);
	for (int i = n - 1; i; i--)
		ifac[i] = mul(ifac[i + 1], i + 1);
}

inline int binom(int a, int b)
{
	if (b > a)
		return 0;
	return mul(fac[a], mul(ifac[b], ifac[a - b]));
}

int f[N], g[N];
int n;

int main()
{
	init(2e6);
	cin >> n;
	for (int i = n; i; i--)
	{
		if (i * 2 > n)
		{
			f[i] = g[i] = 1;
		}
		for (int j = 2; j * i <= n; j++)
		{
			if (f[i * j] + 1 > f[i])
				f[i] = f[i * j] + 1, g[i] = 0;
			if (f[i * j] + 1 == f[i])
			{
				int t1 = n / (i * j), t2 = n / (i);
				g[i] = add(g[i], mul(g[i * j], mul(fac[t2 - t1], binom(n - t1 - 1, t2 - t1 - 1))));
			}
		}
	}
	cout << g[1] << endl;
}

