using namespace std;

long long int n, k;

long long int fact(long long int K){
	if(K <= 1LL) return 1LL;
	return K * fact(K-1);
}

long long int comb(long long int N, long long int K){
	long long int ans = 1LL;
	for(int i = 0; i<K; i++){
		ans *= (N-i);
	} 
	return ans / fact(K);
}

long long int idp(long long int n, long long int k){
	if(k > n) return 0LL; 
	if(k == 0LL) return 1LL;
	if(k == 1LL) return 0LL;
	if(k == 2LL) return comb(n, 2);
	if(k == 3LL) return comb(n, 3)*2LL;
	if(k == 4LL) return comb(n, 4)*9LL;
}

int main(){
	cin >> n >> k;
	long long int ans = 0LL;
	for(int i = 0; i<=k; i++){
		long long int add = idp(n, i);
		ans += add; 
	}
	cout << ans << endl;
}

