bool check(long long mid){
	dp[n] = 0;
	int j = n - 1;
	deque < int > dq;

	for(int i = n - 1;i >= 0;i--){
		while(j > i && sum[j + 1] - sum[i + 1] > mid) j--;

		while((int)dq.size() > 0 && dq.back() > j + 1) dq.pop_back();
		if(j + 1 == n){
			dp[i] = arr[i];
		}
		else{
			dp[i] = arr[i] + dp[dq.back()];
		}
		while((int)dq.size() > 0 && dp[i] <= dp[dq.front()]) dq.pop_front();
		dq.push_front(i);
	}
	for(int i = 0 ;i < n && sum[i] <= mid;i++){
		if(dp[i] <= mid)
			return true;
	}
	return false;
}

