void init() {
	memset(fst, -1, sizeof fst);
	e = 0;
}

void add(int u, int v, int w) {
	vv[e] = v, nxt[e] = fst[u], cost[e] = w, fst[u] = e++;
}

void dfs(int u, int p) {
	dis[u] = 0;
	for(int i = fst[u]; ~i; i = nxt[i]) {
		int v = vv[i];
		if(v== p) continue;
		dfs(v, u);
		dis[u] = max(dis[u], dis[v] + cost[i]);
	}
}

void dfs1(int u, int p, LL mx) {
	dis[u] = max(dis[u], mx);
	LL mx1 = -(1LL<<60), mx2 = -(1LL<<60);
	for(int i = fst[u]; ~i; i = nxt[i]) {
		int v = vv[i];
		if(v == p) continue;
		if(dis[v] + cost[i] >= mx1) mx2 = mx1,mx1 = dis[v] + cost[i];
		else mx2 = max(dis[v] + cost[i], mx2);
	}
	for(int i = fst[u]; ~i; i = nxt[i] ){
		int v = vv[i];
		if(v == p) continue;
		if(mx1 == dis[v] + cost[i]) 
			dfs1(v, u, max(mx + cost[i], mx2 + cost[i]));
		else dfs1(v, u, max(mx, mx1) + cost[i]);
	}
}
LL len;
int sz[N], fa[N];

int find(int x){ 
	return x == fa[x] ? x : fa[x] = find(fa[x]);
}
int id[N];

bool cmp(int a, int b) {
	return dis[a] < dis[b];
}

int cal(int n) {
	int i = n, j = n;
	int ans = 0;
	for(i = n; i >= 1; --i) {
		int u = id[i];
		sz[u] = 1;
		int fu = u;
		for(int k = fst[u]; ~k; k = nxt[k]) {
			int v = vv[k];
			int fv = find(v);
			if(fv == fu || sz[fv] == 0) continue;
			fa[fv] = fu;
			sz[fu] += sz[fv];
		}
		while(j >= i && dis[id[j]] > dis[id[i]] + len) {
			int u = id[j];
			int fu = find(u);
			--sz[fu];
			--j;
		}
		ans = max(ans, sz[fu]);
	}
	return ans;
}
