#include SorahISA __FILE__ SorahISA

void solve() {
    int N, M, K; cin >> N >> M >> K;

    vector<int> H(N);
    for (int &x : H) cin >> x;

    Vec<2, pii> adj(N);
    vector<int> deg_i(N, 0);
    for (int i = 0; i < M; ++i) {
        int a, b; cin >> a >> b, --a, --b;
        adj[a].eb(b, (H[b]-H[a]+K) % K), ++deg_i[b];
    }

    vector<int> head;
    for (int i = 0; i < N; ++i) { if (!deg_i[i]) head.eb(i); }
    sort(ALL(head), [&](int i, int j) { return H[i] < H[j]; });

    vector<int> dis(N, 0);
    for (int x : head) dis[x] = H[x] - H[head[0]];
    for (int i = 0; i < N; ++i) for (auto [x, cost] : adj[i]) chmax(dis[x], dis[i] + cost);

    int time_finish = *max_element(ALL(dis)), ans = time_finish;
    for (int i = 0; i+1 < SZ(head); ++i) {
        /// push head[i] to the next day ///
        /// each event will be pushed back at most once ///

        dis[head[i]] += K;
        prior<int> pq; pq.ee(head[i]); /// id increasing is also topo order
        while (SZ(pq)) {
            int now = pq.top(); pq.pop();
            chmax(time_finish, dis[now]);
            for (auto [x, cost] : adj[now]) { if (chmax(dis[x], dis[now] + cost)) pq.ee(x); }
        }
        chmin(ans, time_finish - dis[head[i+1]]);
    }
    print(ans);
}

