ll mod_exp(ll base, int expo){
	int cop = expo;
	if(cop == 0) return 1;
	if(cop == 1) return base%M;
	ll res = 0;
	ll half = mod_exp(base, floor(cop/2));
	res = (half*half)%M;
	if(cop&1) res *=base;
	return res%M;
