inline int sum(int a, int b) {
  if ((a += b) >= P) {
    a -= P;
  }
  return a;
}

inline int diff(int a, int b) {
  if ((a -= b) < 0) {
    a += P;
  }
  return a;
}

inline int prod(int a, int b) {
  return ll(a) * b % P;
}

inline int& add(int & a, int b) {
  return a = sum(a, b);
}

inline int& mult(int & a, int b) {
  return a = prod(a, b);
}

