LL cal2(int l,int r){
    if(l>r)return 0;
    LL tot=0;
    LL last=r;
    for(int i = 1;;){
        int Next=(r)/(i+1);
        //printf("%d %d %d\n",Next,last,i);
        if(Next<l){
            tot+=cal[i]*(last-l+1);
            break;
        }
        tot+=cal[i]*(last-Next);
        last=Next;
        i=r/Next;
    }
    return tot;
}
