void add(int& a, const int& b) {

    a += b;

    if(a >= MOD) {

        a -= MOD;

    }

    if(a < 0) {

        a += MOD;

    }

}

bool check(int i, int last) {

    FOR(j, 1, i) {

        if(a[j][i] == 0) {

            continue;

        }

        if(a[j][i] == 1 && last >= j) {

            return false;

        }

        if(a[j][i] == 2 && last < j) {

            return false;

        }

    }

    return true;

}

void process(void) {

    memset(dp, 0, sizeof dp);

    dp[1][0] = (a[1][1] != 2 ? 2 : 0);

    FOR(i, 1, n - 1) {

        FOR(j, 0, i - 1) {

            if(dp[i][j] == 0) {

                continue;

            }

            if(check(i + 1, j)) {

                add(dp[i + 1][j], dp[i][j]);

            }

            if(check(i + 1, i)) {

                add(dp[i + 1][i], dp[i][j]);

            }

        }

    }

    int ans = 0;

    FOR(i, 0, n - 1) {

        add(ans, dp[n][i]);

    }

    cout << ans;

}

