void dfs(int u,int f)
{
	siz[u]=1;
	for(int i=1;i<18;i++) fa[u][i]=fa[fa[u][i-1]][i-1];
	for(int v,i=h[u];i;i=e[i].next)
	if((v=e[i].to)!=f) 
	{
		dep[v]=dep[u]+1;
