{
	sum2[u]=last;
	for(int v,i=h[u];i;i=e[i].next)
	if((v=e[i].to)!=f) 
		dfs2(v,u,last+sz+siz[u]-siz[v]+sum[u]-sum[v]-siz[v],sz+siz[u]-siz[v]);
}
int get_lca(int x,int y)
{
	if(dep[x]<dep[y]) swap(x,y);
	int t=dep[x]-dep[y];
	for(int i=0;i<18;i++) 
	if(t&(1<<i)) x=fa[x][i];
	if(x==y) return x;
	for(int i=17;i>=0;i--)
	if(fa[x][i]!=fa[y][i])
		x=fa[x][i],y=fa[y][i];
	return fa[x][0]; 
}
