void dfs(int u, int par) {
    for (int v: adj[u]) if (v != par)
        dfs(v, u);
    for (int i = 1; i <= k; i++) {
        int fl = 0;
        for (int v: adj[u]) if (v != par)
            fl |= (f[v][i - 1] >= 0);
        if (!fl) continue;
        f[u][i] = 0;
        if (i * 2 >= k) {
            for (int v: adj[u]) if (v != par)
                if (f[v][i - 1] >= 0)
                    f[u][i] += f[v][i - 1];
            continue;
        }
        int sum = 0;
        if (k - i - 1 >= 0)
            for (int v: adj[u]) if (v != par)
                sum += max(0, f[v][k - i - 1]);
        for (int v: adj[u]) if (v != par)
            maximize(f[u][i], f[v][i - 1] + sum - (k - i - 1 >= 0 ? max(0, f[v][k - i - 1]) : 0));
    }
    f[u][0] = a[u];
    for (int v: adj[u]) if (v != par)
        f[u][0] += max(0, f[v][k - 1]);
    for (int i = k - 1; i >= 0; i--)
        maximize(f[u][i], f[u][i + 1]);
}

