void factorize(L M, vector<L>&factors, vector<tuple<L,L,L>>&primes) {
  factors.assign(1, 1);
  primes.clear();
  for (L i = 2; i * i <= M; i++) {
    if (M % i == 0) {
      int sz = factors.size();
      L f = 1;
      int facts = 0;
      do {
        facts++;
        M /= i;
        f *= i;
        for (int j = 0; j < sz; j++) {
          factors.push_back(f * factors[j]);
        }
      } while (M % i == 0);
      primes.push_back({i, sz, facts});
    }
  }
  if (M > 1) {
    int sz = factors.size();
    primes.push_back({M, sz, 1});
    for (int j = 0; j < sz; j++) {
      factors.push_back(M * factors[j]);
    }
  }
}
vector<pair<L,int>> buildMapping(vector<L>&original) {
  int n = original.size();
  vector<pair<L,int>> res(n);
  for (int i = 0; i < n; i++) res[i] = {original[i], i};
  sort(res.begin(), res.end());
  return res;
}

