const int SIEVE_MAXN=1000000+5;
int prime[SIEVE_MAXN>100000?SIEVE_MAXN/10:10000];bool bo[SIEVE_MAXN];
int mu[SIEVE_MAXN];
int phi[SIEVE_MAXN];
int nex[SIEVE_MAXN],deg[SIEVE_MAXN];
int sieve(int n){
	int tot=0;
	mu[1]=1;
	phi[1]=1;
	for (int i=2;i<=n;i++){
		if (!bo[i]){
			prime[++tot]=i;
			mu[i]=-1;
			phi[i]=i-1;
			nex[i]=1;
			deg[i]=1;
		}
		for (int j=1;j<=tot && prime[j]*i<=n;j++){
			bo[i*prime[j]]=1;
			if(i%prime[j]==0){
				mu[i*prime[j]]=0;
				phi[i*prime[j]]=phi[i]*prime[j];
				nex[i*prime[j]]=nex[i];
				deg[i*prime[j]]=deg[i]+1;
				break;
			}else{
				mu[i*prime[j]]=-mu[i];
				phi[i*prime[j]]=phi[i]*(prime[j]-1);
				nex[i*prime[j]]=i;
				deg[i*prime[j]]=1;
			}
		}
	}
	return tot;
}


