#include <bits/stdc++.h>
const int MOD = 998244353;
using namespace std;
int n, k;
const int B = 500;
const int N = (int) 1e5 + 10;
int a[N];
int f[N];
int prv[N], used[N];
int c[N];
int ps[N / B + 2][2 * N + 1];
int add[N / B + 2];
int cur_b;

int sum(int x, int y) {
    x += y;
    if (x >= MOD) {
        x -= MOD;
    }
    return x;
}


void md(int l, int val) {
    int b = l / B + 1;
    int cur = 0;
    if (b != cur_b) {
        int y = B - 1;
        int i = b * B - 1;
        while (i >= 1) {
            cur += c[i];
            if (i <= l) {
                if (val == -1) {
                    ps[b][cur + N + val] = sum(ps[b][cur + val + N], f[i - 1]);
                } else {
                    ps[b][cur + N] = sum(ps[b][cur + N], MOD - f[i - 1]);

                }
            }
            y--; i--;
            if (y < 0) {
                break;
            }
        }
    }
    c[l] += val;
    for (int j = 1; j <= l / B; j++) {
        add[j] += val;
    }
}

int calc(int l) {
    int i = l;
    int y = i % B;
    int cur = 0;
    int ans = 0;
    while (i >= 1) {
        cur += c[i];
        if (cur <= k) {
            ans = sum(ans, f[i - 1]);
        }
        y--; i--;
        if (y < 0) {
            break;
        }
    }
    for (int j = 1; j <= l / B; j++) {

        ans = sum(ps[j][k - add[j] + N], ans);
    }

    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        prv[i] = used[a[i]];
        used[a[i]] = i;
    }
    f[0] = 1;
    cur_b = 1;
    for (int i = 1; i <= n; i++) {
        md(i, 1);
        if (prv[i] != 0) {
            if (prv[prv[i]] != 0) {
                md(prv[prv[i]], 1);
            }
            md(prv[i], -1);
            md(prv[i], -1);
        }
        f[i] = calc(i);
        if (i % B == B - 1) {
            int j = i;
            int y = j % B;
            int b = j / B + 1;
            int cur = 0;
            cur_b++;
            while (j >= 1) {
                cur += c[j];
                ps[b][cur + N] = sum(ps[b][cur + N], f[j - 1]);
                y--; j--;
                if (y < 0) {
                    break;
                }
            }
            for (int k = 1; k <= 2 * N; k++) {
                ps[b][k] = sum(ps[b][k], ps[b][k - 1]);
            }
        }
    }
    cout << f[n] << "\n";

    return 0;
}

