int rmq_min[N][M], rmq_max[N][M];



void init(const int a[])

{

    for (int j = 0; j < M; ++ j)

        for (int i = 1; i + (1 << j) - 1 <= n; ++ i)

        {

            if (!j)	 rmq_min[i][j] = a[i];

            else	rmq_min[i][j] = min(rmq_min[i][j - 1], rmq_min[i + (1 << j - 1)][j - 1]);

            if (!j)	 rmq_max[i][j] = a[i];

            else	rmq_max[i][j] = max(rmq_max[i][j - 1], rmq_max[i + (1 << j - 1)][j - 1]);

        }

}



int query_max(int l, int r)

{

    int len = r - l + 1;

    int k = __lg(len);

    return max(rmq_max[l][k], rmq_max[r - (1 << k) + 1][k]);

}



int query_min(int l, int r)

{

    int len = r - l + 1;

    int k = __lg(len);

    return min(rmq_min[l][k], rmq_min[r - (1 << k) + 1][k]);

}



