const ll maxn=2e5+10, inf=1e17;
ll n,res[maxn],len,deg[maxn],rt;
vector<ll>to[maxn];
void dfs(ll u,ll fa,ll chs){
	ll d=0;
	for(ll v:to[u])
		if(v!=fa&&deg[v]>1) ++d;
	if((d-(u==rt))>1){
		puts("No"); exit(0);
	}
	if(u==rt){ ll x=0; res[len=1]=rt;
		for(ll v:to[u])
			if(deg[v]>1){
				x=v; dfs(v,u,0); break;
			}
		for(ll v:to[u])
			if(deg[v]==1) res[++len]=v;
		for(ll v:to[u])
			if(deg[v]>1&&x!=v) dfs(v,u,1);
		return;
	}
	if(chs){
		res[++len]=u;
		for(ll v:to[u])
			if(v!=fa&&deg[v]>1) dfs(v,u,0);
		for(ll v:to[u])
			if(v!=fa&&deg[v]==1) res[++len]=v;
	} else{
		for(ll v:to[u])
			if(v!=fa&&deg[v]==1) res[++len]=v;
		for(ll v:to[u])
			if(v!=fa&&deg[v]>1) dfs(v,u,1);
		res[++len]=u;
	}
}
