 vector<VL> now;
 rept(it, L(sm[v])) {
  int w = sm[v][it];
  if (w == pr) continue;
  now.swap(nx);
  int ss = L(now) + L(dp[w]) - 2;
  nx.resize(ss + 1);
  rept(i, L(nx)) {
   nx[i].resize(ss + 1);
   rept(j, L(nx[i])) nx[i][j] = 0;
  }


  rept(i, L(now)) {
   rept(j, L(now[i])) {
    if (i + j > L(now)) break;
    if (!now[i][j]) continue;
    now[i][j] %= MOD;

    rept(ii, L(dp[w])) {
     rept(jj, L(dp[w][ii])) {
      if (ii + jj > L(dp[w])) break;
      if (!dp[w][ii][jj]) continue;

      // Take the edge
      add(nx[i + ii - 1][j + jj], now[i][j] * dp[w][ii][jj]);

      // Don't take the edge
      add(nx[i + ii][j], now[i][j] * mul[w][ii][jj]);
     }
    }
   }
  }
 }

 dp[v].resize(L(nx));
 mul[v].resize(L(nx));
 rept(i, L(nx)) {
  dp[v][i].resize(L(nx[i]));
  mul[v][i].resize(L(nx[i]));
  rept(j, L(nx[i])) {
   dp[v][i][j] = nx[i][j] % MOD;
   mul[v][i][j] = (ll)dp[v][i][j] * j % MOD;
  }
 }
}
