struct FenwickTree {
    vector<ll> t;
    int n;

    FenwickTree(int N) {
        n = N;
        t.resize(n);
    }

    ll sum(int r) {
        ll res = 0;
        while (r >= 0) {
            res += t[r];
            r = (r & (r + 1)) - 1;
        }
        return res;
    }

    void inc(int i, ll d) {
        while (i < n) {
            t[i] += d;
            i = (i | (i + 1));
        }
    }

    ll sum(int l, int r) {
        if (l > r)
            return 0ll;
        return sum(r) - sum(l - 1);
    }
};

