const int Mod=998244353;

int n,m,ans,a[N],b[N],c[N<<1],f[N],g[N];

int qpow(int x,int k)

{	int res=1;

	while(k)

	{	if(k&1)res=1ll*res*x%Mod;

		x=1ll*x*x%Mod,k>>=1;

	}

	return res;

}

