    while (!((ch >= '0' && ch <= '9') || ch == '-')) ch = getchar();

    int x = 0, p = 1;

    if (ch == '-') p = -1, ch = getchar();

    while (ch >= '0' && ch <= '9') x = x * 10 + ch - '0', ch = getchar();

    return x * p;

}



inline int get(int l, int r) {

    return a[r][r] - a[l][r] - a[r][l] + a[l][l];

}



int main() {



    int n, k;

    scanf("%d %d", &n, &k);



    for(int i = 1;i <= n;i++) {

        for(int j = 1;j <= n;j++) {

