            a[i][j] = a[i - 1][j] + a[i][j - 1] - a[i - 1][j - 1] + a[i][j];

        }

    }



    for(int i = 1;i <= n;i++) {

        dp[1][i] = get(0, i);

        best[1][i] = 1;

    }



    for(int j = 2;j <= k;j++) {

