#include <bits/stdc++.h>
const long long inf = 1e18;
int n, m, k;
std::vector <int> vc[200005];
long long ans = inf;
int rd[200005], h[200005], tp[200005], cnt, d[200005], is[200005];
long long dp[200005];
long long f[200005], g[200005];
void solve(){
  scanf("%d%d%d", &n, &m, &k); ans = inf;
  for(int i = 1; i <= n; ++i) vc[i].clear(), rd[i] = 0;
  for(int i = 1; i <= n; ++i) scanf("%d", &h[i]);
  for(int i = 1; i <= m; ++i){
    int x, y;
    scanf("%d%d", &x, &y);
    ++rd[y];
    vc[x].push_back(y);
  }
  std::queue <int> q; cnt = 0;
  for(int i = 1; i <= n; ++i) if(!rd[i]) q.push(i), is[i] = 1; else is[i] = 0;
  while(q.size()){
    int u = q.front(); q.pop();
    tp[++cnt] = u;
    for(auto v : vc[u]){
      --rd[v];
      if(rd[v] == 0) q.push(v);
    }
  }
  for(int i = n; i >= 1; --i){
    int u = tp[i];
    dp[u] = 0ll;
    for(auto v : vc[u]){
      if(h[u] <= h[v]) dp[u] = std::max(dp[u], dp[v] + 1ll * h[v] - 1ll * h[u]);
      else dp[u] = std::max(dp[u], dp[v] + 1ll * k + 1ll * h[v] - 1ll * h[u]);
    }
  }
 // printf("%lld\n", dp[1]);
  for(int i = 1; i <= n; ++i) d[i] = i;
  std::sort(d + 1, d + n + 1, [&](int x, int y){
    return h[x] < h[y];
  });
  f[0] = -inf, g[n + 1] = -inf;
  for(int i = 1; i <= n; ++i){
    f[i] = f[i - 1];
    if(is[d[i]]) f[i] = std::max(f[i], dp[d[i]] + 1ll * k + 1ll * h[d[i]]);
  }
  for(int i = n; i >= 1; --i){
    g[i] = g[i + 1];
    if(is[d[i]]) g[i] = std::max(g[i], dp[d[i]] + 1ll * h[d[i]]);
  }
  for(int i = 1; i <= n; ++i){
    if(!is[d[i]]) continue;
    long long r = dp[d[i]];
    r = std::max(r, f[i - 1] - 1ll * h[d[i]]);
    r = std::max(r, g[i + 1] - 1ll * h[d[i]]);
    ans = std::min(ans, r);
  }
  printf("%lld\n", ans);
  return ;
}
int main(){
  int T = 1;
  scanf("%d", &T);
  while(T--) solve();
  return 0;
}

