int ans = 0;

int dfs(int v, int p, vector<int> &color, vector<int> adj[]) {

	int cnt = color[v];

	for (auto &u : adj[v]) {

		if (u != p) {

			cnt += dfs(u, v, color, adj);

		}

	}

	if (cnt == 0) ans++;

	return cnt;

}



void solve() {

	int n;

	cin >> n;

	vector<int> adj[n + 1], color(n + 1);

	for (int i = 2; i <= n; i++) {

		int p; cin >> p;

		adj[i].pb(p);

		adj[p].pb(i);

	}

	for (int i = 1; i <= n; i++) {

		char ch; cin >> ch;

		if (ch == 'W') color[i] = 1;

		else color[i] = -1;

	}

	dfs(1, 0, color, adj);

	cout << ans << "\n";

	ans = 0;

}



