#include <bits/stdc++.h>
using namespace std;
const int N=100005;
typedef long long LL;
int st[N][18],head[N],cnt=0;
struct edge
{
    int n,t;
    edge(int a=0,int b=0):n(a),t(b){}
}e[N<<1];
int d[N];
LL s1[N],s2[N],sz[N];
void ins(int a,int b)
{
    e[cnt]=edge(head[a],b);
    head[a]=cnt++;
}
int n,m;
void dfs(int u,int p,int dep=1)
{
    int i,v;
    st[u][0]=p;
    sz[u]=1;
    d[u]=dep;
    for(i=head[u];i!=-1;i=e[i].n)
    {
        v=e[i].t;
        if(v==p)
            continue;
        dfs(v,u,dep+1);
        sz[u]+=sz[v];
        s1[u]+=s1[v]+sz[v];
    }
}
void dfs2(int u,int p)
{
    int i,v;
    for(i=head[u];i!=-1;i=e[i].n)
    {
        v=e[i].t;
        if(v==p)
            continue;
        s2[v]=s2[u]+(n-(sz[v]<<1));
        dfs2(v,u);
    }
}
int lca(int a,int b)
{
    if(a==b)
        return a;
    if(d[a]>d[b])
        swap(a,b);
    if(d[b]>d[a])
    {
        for(int i=1<<17,j=17;j>=0&&i>=0;i>>=1,--j)
            if(d[b]-d[a]>=i)
                b=st[b][j];
    }
    if(a==b)
        return a;
    for(int j=17;j>=0;--j)
        if(st[b][j]!=st[a][j])
        {
            b=st[b][j];
            a=st[a][j];
        }
    return st[b][0];
}
double calc(int a,int b)
{
    int i,u,v,tt;
    if(d[a]>d[b])
        swap(a,b);
    tt=lca(a,b);
    double ans=d[a]-(d[tt]<<1)+d[b]+1;
    if(a!=tt)
    {
        ans+=1.0*s1[a]/sz[a];
        ans+=1.0*s1[b]/sz[b];
        return ans;
    }
    ans+=1.0*s1[b]/sz[b];
    int dd=d[b]-d[a]-1;
    for(i=17;i>=0;--i)
    {
        if((1<<i)<=dd)
        {
            dd-=(1<<i);
            b=st[b][i];
        }
    }
    ans+=1.0*(s2[a]-sz[b]-s1[b])/(n-sz[b]);
    return ans;
}
int main()
{
    int i,j,a,b;
    scanf("%d%d",&n,&m);
    memset(head,-1,sizeof(head));
    for(i=1;i<n;++i)
    {
        scanf("%d%d",&a,&b);
        ins(a,b);ins(b,a);
    }
    dfs(1,1);
    s2[1]=s1[1];
    dfs2(1,1);
    for(i=1;i<=17;++i)
    {
        for(j=1;j<=n;++j)
            st[j][i]=st[st[j][i-1]][i-1];
    }
    while(m--)
    {
        scanf("%d%d",&a,&b);
        printf("%.10lf\n",calc(a,b));
    }
    return 0;
}

