vector<pair<int, int>> pos[maxn];
int dp[maxn];

void add(int& x, int y) {
  x += y;
  if (x >= mod) {
    x -= mod;
  }
}

void sub(int& x, int y) {
  x -= y;
  if (x < 0) {
    x += mod;
  }
}

int total = 0;

const int szb = 330;
const int cntb = 330;

int cnt[maxn];
int freq[cntb][maxn];
int global[cntb];
int k;

void incseg(int l, int r) {
//  cout << "incseg" << ' ' << l << ' ' << r << ' ';
//  cout << total << endl;
  int L = l / szb;
  for (int i = l; i <= r; ++i) {
    sub(freq[L][cnt[i]], dp[i - 1]);
    if (cnt[i] + global[L] == k) {
      sub(total, dp[i - 1]);
    }
    cnt[i]++;
    add(freq[L][cnt[i]], dp[i - 1]);
  }
//  cout << total << endl;
}

int getondep(int i, int j) {
  if (j < 0) return 0;
  return freq[i][j];
}

void inc(int l, int r) {
  int L = l / szb;
  int R = r / szb;
  if (L == R) {
    incseg(l, r);
  } else {
    incseg(l, szb * (L + 1) - 1);
    incseg(szb * R, r);
    for (int i = L + 1; i < R; ++i) {
      sub(total, getondep(i, k - global[i]));
      ++global[i];
    }
  }
}

void decseg(int l, int r) {
//  cout << "decseg" << ' ' << l << ' ' << r << ' ';
//  cout << total << endl;
  int L = l / szb;
  for (int i = l; i <= r; ++i) {
    sub(freq[L][cnt[i]], dp[i - 1]);
    cnt[i]--;
    add(freq[L][cnt[i]], dp[i - 1]);
    if (cnt[i] + global[L] == k) {
      add(total, dp[i - 1]);
    }
  }
}


void dec(int l, int r) {
  int L = l / szb;
  int R = r / szb;
  if (L == R) {
    decseg(l, r);
  } else {
    decseg(l, szb * (L + 1) - 1);
    decseg(szb * R, r);
    for (int i = L + 1; i < R; ++i) {
      --global[i];
      add(total, getondep(i, k - global[i]));
    }
  }
}

